345	
346	  /* Kortet självt. Rotationen räknas i ren CSS ur --sc-ps:
347	       t    = clamp(0, (ps - 0.12) / 0.6, 1)
348	       flip = t*t*(3 - 2t)                         (smoothstep 0.12 -> 0.72)
349	     ps 0 till 0,12: flip 0, kortet stilla medan ljuspölen vandrar.
350	     ps 0,12 till 0,72: vändningen.
351	     ps 0,72 till 1: flip 1, baksidan i vila, dwell låter den landa.
