   Scrollpositionen räknas ur SAMMA formel som readState:s processPs()
   löst för scrollY, inte scrollIntoView + scrollBy: scrollIntoView
   ('start') landar på ps ≈ innerHeight/life (0,25 vid 900px), inte på
   ps 0, så ett efterföljande scrollBy(mid * life) landade på ps ≈
   0,25 + mid, långt bortom sticky-hållets faktiska fönster (MÄTT:
   process-05 visade footerns adress bakom arket, inte Calyx-fyllningen).
   scrollY = top + mid*life - innerHeight ger rätt ps direkt.
   sc-smooth.js:s frysta tick skriver ändå OM --sc-ps mot motorns egen
   rå-progress för varje scroll-utlöst omräkning, så värdet skrivs om en
   gång per bildruta i 20 rutor EFTER scrollen: sista skrivningen i den
   slingan vinner alltid, oavsett hur många scroll-utlösta omräkningar
   hinner interfoliera, eftersom ingen ny scroll sker efter den
   initiala hoppningen och shimen därför slutar skriva när slingan är
   klar. */
var PROCESS_MID = { '01':0.235, '02':0.325, '03':0.415, '04':0.505,
                     '05':0.595, '06':0.685, '07':0.90 };
if (mode && /^process-0[1-7]$/.test(mode) && process){
  var pn = mode.slice(-2);
  var mid = PROCESS_MID[pn];
  var pr0 = process.getBoundingClientRect();
  var top0 = pr0.top + window.scrollY;
  var life = pr0.height + window.innerHeight;
  window.scrollTo(0, top0 + mid * life - window.innerHeight);
  var forceFrames = 0;
  (function forcePs(){
    process.style.setProperty('--sc-ps', String(mid));
    forceFrames++;
    if (forceFrames < 20) requestAnimationFrame(forcePs);
